(()=>{const area=document.getElementById('intent');if(!area)return;const resize=()=>{area.style.height='auto';area.style.height=Math.min(area.scrollHeight,168)+'px';area.style.overflowY=area.scrollHeight>168?'auto':'hidden'};area.addEventListener('input',resize);document.querySelectorAll('[data-role]').forEach(button=>button.addEventListener('click',()=>requestAnimationFrame(resize)));const share=document.querySelector('[data-role-jump="person"]');if(share)share.onclick=()=>{document.querySelector('[data-role="person"]')?.click();requestAnimationFrame(()=>{area.scrollIntoView({behavior:'smooth',block:'center'});setTimeout(()=>area.focus({preventScroll:true}),450)})};resize()})();
